(function(){
'use strict';
var FLAGS={
 '-i':'输入文件','-y':'覆盖已存在的输出文件','-n':'输出已存在时直接退出',
 '-c':'统一指定编解码器','-c:v':'视频编码器','-c:a':'音频编码器','-c:s':'字幕编码器',
 '-vcodec':'视频编码器（旧写法，等价 -c:v）','-acodec':'音频编码器（旧写法，等价 -c:a）',
 '-crf':'恒定质量因子，数字越小画质越好体积越大（x264/x265 常用 18-28）',
 '-preset':'编码速度预设，越慢压缩率越高（ultrafast~veryslow）',
 '-tune':'针对内容类型调优（film/animation/grain/zerolatency 等）',
 '-profile:v':'编码 profile（baseline/main/high），影响兼容性',
 '-level':'编码 level，限制码率与分辨率上限',
 '-b:v':'视频目标码率','-b:a':'音频目标码率','-maxrate':'最大码率上限','-bufsize':'码率控制缓冲区大小',
 '-vf':'视频滤镜链','-af':'音频滤镜链','-filter_complex':'复杂滤镜图（多输入/多输出）',
 '-r':'输出帧率','-s':'输出分辨率（等价 scale 滤镜）','-aspect':'显示宽高比',
 '-ss':'起始时间点（放在 -i 前为快速定位）','-t':'持续时长','-to':'结束时间点',
 '-an':'去掉音频流','-vn':'去掉视频流','-sn':'去掉字幕流','-dn':'去掉数据流',
 '-map':'手动选择要输出的流','-f':'强制指定容器格式','-pix_fmt':'像素格式（yuv420p 兼容性最好）',
 '-ar':'音频采样率','-ac':'音频声道数','-q:v':'视频质量（可变码率编码器）','-q:a':'音频质量',
 '-movflags':'MP4 容器标志，+faststart 可让网页边下边播',
 '-threads':'编码线程数','-hwaccel':'硬件解码加速（cuda/qsv/videotoolbox 等）',
 '-loop':'循环输入次数','-shortest':'以最短的流为准结束输出','-stream_loop':'输入循环次数',
 '-metadata':'写入元数据','-pass':'两遍编码的第几遍','-g':'关键帧间隔（GOP）',
 '-re':'按原生帧率读取（推流常用）','-vsync':'帧同步策略','-copyts':'保留原始时间戳',
 '-itsoffset':'输入时间偏移','-disposition':'设置流的默认/强制标记','-hide_banner':'隐藏版本横幅',
 '-loglevel':'日志级别','-progress':'输出进度到指定目标','-nostdin':'禁止读取标准输入'
};
var VALUELESS={'-y':1,'-n':1,'-an':1,'-vn':1,'-sn':1,'-dn':1,'-shortest':1,'-re':1,'-copyts':1,'-hide_banner':1,'-nostdin':1};
var PRESETS=[
 {id:'compress',name:'压缩视频（H.264）',o:{vcodec:'libx264',crf:'23',preset:'medium',acodec:'aac',abitrate:'128k',faststart:true}},
 {id:'h265',name:'转 H.265 省一半体积',o:{vcodec:'libx265',crf:'28',preset:'medium',acodec:'aac',abitrate:'128k',tag:'hvc1'}},
 {id:'web',name:'网页可流式播放 MP4',o:{vcodec:'libx264',crf:'22',preset:'slow',acodec:'aac',abitrate:'128k',pix:'yuv420p',faststart:true}},
 {id:'gif',name:'视频转高质量 GIF',o:{gif:true,fps:'12',scale:'480'}},
 {id:'audio',name:'提取音频为 MP3',o:{novideo:true,acodec:'libmp3lame',abitrate:'192k',ext:'mp3'}},
 {id:'mute',name:'去掉声音',o:{vcodec:'copy',mute:true}},
 {id:'cut',name:'无损截取片段',o:{vcodec:'copy',acodec:'copy',start:'00:00:10',duration:'00:00:30'}},
 {id:'shrink',name:'缩放到 720p',o:{vcodec:'libx264',crf:'23',preset:'medium',scale:'1280',acodec:'aac',abitrate:'128k'}},
 {id:'frames',name:'每秒抽一帧存图',o:{frames:true,fps:'1'}},
 {id:'rotate',name:'顺时针旋转 90 度',o:{vcodec:'libx264',crf:'20',preset:'medium',transpose:'1',acodec:'copy'}}
];
function q(s){ return /[\s"'*?$&|<>()]/.test(s)?('"'+String(s).replace(/"/g,'\\"')+'"'):s; }
function baseName(p){ var b=String(p).split(/[\\/]/).pop(); var i=b.lastIndexOf('.'); return i>0?b.slice(0,i):b; }
function build(o){
  o=o||{};
  var input=o.input||'input.mp4';
  if(!String(input).trim()) return {value:null,error:'请填写输入文件名'};
  var a=['ffmpeg'],vf=[],notes=[];
  if(o.overwrite!==false) a.push('-y');
  if(o.hwaccel) a.push('-hwaccel',o.hwaccel);
  if(o.start) a.push('-ss',o.start);
  a.push('-i',q(input));
  if(o.duration) a.push('-t',o.duration);
  if(o.scale) vf.push('scale='+o.scale+':-2');
  if(o.transpose) vf.push('transpose='+o.transpose);
  if(o.fps&&!o.gif) a.push('-r',o.fps);
  if(o.gif){
    vf.push('fps='+(o.fps||'12'));
    vf.push('split[a][b];[a]palettegen=stats_mode=diff[p];[b][p]paletteuse=dither=bayer');
    a.push('-vf',q(vf.join(',')));
    a.push('-loop','0');
    var gout=o.output||(baseName(input)+'.gif');
    a.push(q(gout));
    notes.push('使用 palettegen/paletteuse 两段调色板滤镜，GIF 色彩明显优于直接转换');
    return {value:{cmd:a.join(' '),notes:notes,filters:vf.slice()},error:null};
  }
  if(o.frames){
    if(o.fps) a.push('-vf',q('fps='+o.fps));
    a.push('-q:v','2');
    a.push(q(o.output||'frame_%04d.jpg'));
    notes.push('%04d 会展开为 frame_0001.jpg 这样的序号文件名');
    return {value:{cmd:a.join(' '),notes:notes,filters:[]},error:null};
  }
  if(vf.length) a.push('-vf',q(vf.join(',')));
  if(o.novideo){ a.push('-vn'); }
  else if(o.vcodec){ a.push('-c:v',o.vcodec); }
  if(o.vcodec&&o.vcodec!=='copy'&&!o.novideo){
    if(o.crf) a.push('-crf',o.crf);
    if(o.preset) a.push('-preset',o.preset);
    if(o.tune) a.push('-tune',o.tune);
    if(o.pix) a.push('-pix_fmt',o.pix);
    if(o.tag) a.push('-tag:v',o.tag);
  }
  if(o.mute) a.push('-an');
  else if(o.acodec){ a.push('-c:a',o.acodec); if(o.acodec!=='copy'&&o.abitrate) a.push('-b:a',o.abitrate); }
  if(o.faststart) a.push('-movflags','+faststart');
  if(o.extra) a.push(o.extra);
  var ext=o.ext||(o.novideo?'mp3':'mp4');
  a.push(q(o.output||(baseName(input)+'_out.'+ext)));
  if(o.vcodec==='copy'&&o.start) notes.push('流复制截取只能在关键帧处切，起止点可能有 1-2 秒偏差');
  if(o.vcodec==='libx265') notes.push('加 -tag:v hvc1 才能被苹果设备与 Safari 正常识别');
  if(o.faststart) notes.push('+faststart 把索引挪到文件头，网页可边下边播');
  if(o.crf&&Number(o.crf)<18) notes.push('CRF 低于 18 时体积会迅速膨胀，肉眼收益有限');
  return {value:{cmd:a.join(' '),notes:notes,filters:vf.slice()},error:null};
}
function tokenize(s){
  var t=[],cur='',q0=0,i,c,has=false;
  for(i=0;i<s.length;i++){
    c=s.charAt(i);
    if(q0===0){
      if(c==='"'){q0=1;has=true;continue;}
      if(c==="'"){q0=2;has=true;continue;}
      if(/\s/.test(c)){ if(cur||has){t.push(cur);cur='';has=false;} continue; }
      if(c==='\\'&&i+1<s.length&&s.charAt(i+1)==='\n'){i++;continue;}
      cur+=c;
    } else if(q0===1){ if(c==='"'){q0=0;continue;} if(c==='\\'&&i+1<s.length){cur+=s.charAt(++i);continue;} cur+=c; }
    else { if(c==="'"){q0=0;continue;} cur+=c; }
  }
  if(cur||has)t.push(cur);
  return t;
}
function explain(cmd){
  if(typeof cmd!=='string'||!cmd.trim()) return {value:null,error:'请粘贴一条 ffmpeg 命令'};
  var t=tokenize(cmd.replace(/\s*\\\s*\n\s*/g,' '));
  if(!t.length) return {value:null,error:'请粘贴一条 ffmpeg 命令'};
  if(!/^ffmpeg(\.exe)?$/i.test(t[0])) return {value:null,error:'命令需要以 ffmpeg 开头'};
  var rows=[],warn=[],inputs=[],outputs=[],i=1;
  while(i<t.length){
    var tk=t[i];
    if(tk.charAt(0)==='-'){
      var key=tk,desc=FLAGS[key];
      if(!desc){
        var b=key.split(':')[0];
        desc=FLAGS[b]?(FLAGS[b]+'（作用于 '+key.split(':').slice(1).join(':')+' 流）'):null;
      }
      var val='';
      if(!VALUELESS[key]&&i+1<t.length&&(t[i+1].charAt(0)!=='-'||/^-?\d/.test(t[i+1]))){ val=t[i+1]; i++; }
      if(key==='-i') inputs.push(val);
      rows.push({flag:key,arg:val,desc:desc||'未收录的参数，请查阅 ffmpeg 官方文档'});
      if(!desc) warn.push('未识别参数 '+key);
    } else {
      outputs.push(tk);
      rows.push({flag:'',arg:tk,desc:'输出文件'});
    }
    i++;
  }
  if(!inputs.length) warn.push('没有找到 -i 输入文件');
  if(!outputs.length) warn.push('没有找到输出文件');
  var joined=' '+t.join(' ')+' ';
  if(joined.indexOf(' -c:v copy ')>=0&&joined.indexOf(' -vf ')>=0) warn.push('-c:v copy 与 -vf 冲突：流复制时无法应用视频滤镜');
  if(joined.indexOf(' -crf ')>=0&&joined.indexOf(' -c:v copy ')>=0) warn.push('-crf 对 -c:v copy 无效');
  if(/\.mp4["']?\s*$/.test(cmd)&&joined.indexOf('faststart')<0) warn.push('输出 MP4 建议加 -movflags +faststart 以支持网页流式播放');
  return {value:{rows:rows,inputs:inputs,outputs:outputs,warn:warn,count:rows.length},error:null};
}
var API={build:build,explain:explain,tokenize:tokenize,PRESETS:PRESETS,FLAGS:FLAGS,baseName:baseName,quote:q};
if(typeof module!=='undefined'&&module.exports) module.exports=API;
if(typeof window!=='undefined') window.__FfmpegForge__=API;
})();
